#include <vector>
#include <queue>
#include <algorithm>

class Solution {
public:
    int maxPerformance(int n, std::vector<int>& speed, std::vector<int>& efficiency, int k) {
        std::vector<std::pair<int, int>> eng(n);
        for (int i = 0; i < n; ++i) eng[i] = {efficiency[i], speed[i]};
        std::sort(eng.rbegin(), eng.rend());
        std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
        long long speedSum = 0, maxPerf = 0;
        for (const auto& [eff, spd] : eng) {
            minHeap.push(spd);
            speedSum += spd;
            if ((int)minHeap.size() > k) {
                speedSum -= minHeap.top();
                minHeap.pop();
            }
            maxPerf = std::max(maxPerf, speedSum * eff);
        }
        return maxPerf % 1000000007;
    }
};

import java.util.*;

class Solution {
    public int maxPerformance(int n, int[] speed, int[] efficiency, int k) {
        int[][] eng = new int[n][2];
        for (int i = 0; i < n; i++) {
            eng[i][0] = efficiency[i];
            eng[i][1] = speed[i];
        }
        Arrays.sort(eng, (a, b) -> Integer.compare(b[0], a[0]));
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        long speedSum = 0, maxPerf = 0;
        for (int[] e : eng) {
            int eff = e[0], spd = e[1];
            minHeap.offer(spd);
            speedSum += spd;
            if (minHeap.size() > k) {
                speedSum -= minHeap.poll();
            }
            maxPerf = Math.max(maxPerf, speedSum * eff);
        }
        return (int)(maxPerf % 1000000007L);
    }
}

var maxPerformance = function(n, speed, efficiency, k) {
    const eng = [];
    for (let i = 0; i < n; i++) eng.push([efficiency[i], speed[i]]);
    eng.sort((a, b) => b[0] - a[0]);
    const minHeap = [];
    const push = (val) => {
        minHeap.push(val);
        let i = minHeap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (minHeap[p] <= minHeap[i]) break;
            [minHeap[p], minHeap[i]] = [minHeap[i], minHeap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = minHeap[0];
        const bottom = minHeap.pop();
        if (minHeap.length > 0) {
            minHeap[0] = bottom;
            let i = 0;
            while (true) {
                let left = 2 * i + 1, right = 2 * i + 2, best = i;
                if (left < minHeap.length && minHeap[left] < minHeap[best]) best = left;
                if (right < minHeap.length && minHeap[right] < minHeap[best]) best = right;
                if (best === i) break;
                [minHeap[i], minHeap[best]] = [minHeap[best], minHeap[i]];
                i = best;
            }
        }
        return top;
    };
    let speedSum = 0n, maxPerf = 0n;
    for (const [eff, spd] of eng) {
        push(spd);
        speedSum += BigInt(spd);
        if (minHeap.length > k) {
            speedSum -= BigInt(pop());
        }
        const perf = speedSum * BigInt(eff);
        if (perf > maxPerf) maxPerf = perf;
    }
    return Number(maxPerf % 1000000007n);
};
